import json
import re


def slugify(name):
    s = re.sub(r"[^a-z0-9]+", "-", str(name or "").lower()).strip("-")
    return s[:40].strip("-") or "practice"


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def answer(responses, qid):
    return (responses or {}).get(qid)


def lookup_id(value):
    if isinstance(value, dict):
        return value.get("id") or None
    return None


def norm(name):
    s = re.sub(r"[^a-z0-9 ]+", " ", str(name or "").lower())
    s = re.sub(r"\b(pty|ltd|limited|p/l|the|inc|co)\b", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def xero_connections():
    res = api.connectors.invoke(server="xero-accounting", tool="list_connections", args={})
    if isinstance(res, dict):
        res = res.get("connections") or res.get("tenants") or []
    return [c for c in (res or []) if isinstance(c, dict)]


responses = params.get("responses") or {}
todo_id = params.get("todo_id") or ""
actor = params.get("actor") or ""
outcome = "ignored"


def note(body, done=True):
    if not todo_id:
        return
    api.workq.comment(todo_id=todo_id, body=body)
    if done:
        api.workq.complete(todo_id=todo_id)


if not responses:
    # No answers: the Publish practice run sends a sample event with an empty payload.
    outcome = "ignored"
else:
    name = str(answer(responses, "q_practice_name") or "").strip()
    slug = slugify(name)
    business_id = str(answer(responses, "q_cliniko_business_id") or "").strip()
    email_choice = str(answer(responses, "q_email_provider") or "")
    email_provider = "outlook" if email_choice.lower().startswith("outlook") else "gmail"
    org_name = str(answer(responses, "q_xero_org") or "").strip()
    xero_tenant_id = ""
    xero_org_matched = ""

    if org_name:
        connections = xero_connections()
        match = None
        for c in connections:
            if norm(c.get("tenantName")) == norm(org_name):
                match = c
                break
        if not match:
            for c in connections:
                if norm(org_name) and norm(org_name) in norm(c.get("tenantName")):
                    match = c
                    break
        if match:
            xero_tenant_id = match.get("tenantId") or ""
            xero_org_matched = match.get("tenantName") or ""
        else:
            available = ", ".join(sorted(str(c.get("tenantName")) for c in connections)) or "none"
            note(
                "I couldn't find a Xero organisation called **" + org_name + "** in this automation's owner's Xero "
                "connection.\n\nOrganisations available: " + available + ".\n\nSubmit the Practice setup form again "
                "with the name exactly as it appears in Xero, or leave it blank if this practice doesn't use Xero yet.",
                done=False,
            )
            outcome = "xero_org_not_found"

    if outcome != "xero_org_not_found":
        timezone = str(answer(responses, "q_timezone") or "").strip() or "Australia/Sydney"
        window_raw = str(answer(responses, "q_cancellation_window") or "").strip()
        try:
            cancellation_window_hours = int(float(window_raw)) if window_raw else 24
        except ValueError:
            cancellation_window_hours = 24
        reviewer_id = lookup_id(answer(responses, "q_reviewer"))

        practice = {
            "slug": slug,
            "name": name,
            "cliniko_business_id": business_id,
            "email_provider": email_provider,
            "xero_tenant_id": xero_tenant_id,
            "timezone": timezone,
            "policy": {
                "cancellation_window_hours": cancellation_window_hours,
                "tone": "warm, concise, no jargon",
                "email_tiers": [
                    {"key": "clinical", "label": "Reschedules, cancellations, results", "mode": "approve"},
                    {"key": "patient_query", "label": "Patient queries", "mode": "approve"},
                    {"key": "industry", "label": "Industry news and newsletters", "mode": "auto"},
                ],
                "payer_addressing": "parent_or_guardian_when_patient_is_a_child",
                "approval_required_for": ["patient_facing_email", "diary_change", "invoice_status_change"],
                "never_do": [
                    "give clinical advice, diagnosis or interpretation",
                    "threaten fees or legal action on an overdue account",
                    "mark a Cliniko invoice as paid or closed (the API is read-only for invoices)",
                    "store a card or bank account number",
                ],
            },
            "digest_recipient_ids": [x for x in [reviewer_id] if x],
            "reviewer_id": reviewer_id or "",
        }
        write_json("PracticeManager/Practices/" + slug + ".json", practice)
        if read_json("PracticeManager/Commitments/" + slug + ".json") is None:
            write_json("PracticeManager/Commitments/" + slug + ".json", [])
        outcome = "practice_saved"
        xero_note = ("Xero: " + xero_org_matched) if xero_org_matched else "Xero: not set up yet"
        note(
            "Saved practice settings for **" + name + "** (slug `" + slug + "`). " + xero_note + ".\n\n"
            "The Practice Manager Agent can now read `PracticeManager/Practices/" + slug + ".json` for this practice.\n\n"
            "Sensible defaults were applied for tone, email tiers, approval rules and the never-do list \u2014 edit "
            "`PracticeManager/Practices/" + slug + ".json` directly in Knowledge to change them."
        )
